import React from 'react';
import CodeBlock from '@theme/CodeBlock';
// @ts-ignore — generated by `npm run build:plugin-godocs` (from docs/site); gitignored build
// output, see docs/site/.gitignore.
import rawDocs from '@site/data/plugin-godocs.json';
import type {GoDocs} from '../PluginGoDocs/types';

const docs: GoDocs | undefined = rawDocs && Object.keys(rawDocs).length > 0 ? (rawDocs as GoDocs) : undefined;

/**
 * Renders a single Go example's source code, sourced from the same generated data as
 * `<PluginGoDocs />`, e.g. `<PluginGoExample name="_helloWorld" />` renders the body of
 * `Example_helloWorld`.
 */
export default function PluginGoExample({name}: {name: string}) {
  const example = docs?.Examples?.[name];
  if (!example) {
    return (
      <p>
        Run <code>npm run build:plugin-godocs</code> (from <code>docs/site</code>) to generate this
        example code.
      </p>
    );
  }
  return <CodeBlock language="go">{example.Code}</CodeBlock>;
}
